package org.icu.sepsis.timeline;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.ObjectProvider;import org.icu.sepsis.integration.*;import org.icu.sepsis.domain.Domain.*;import org.icu.sepsis.sepsis.Icu05Rules;import org.icu.sepsis.api.ApiException;
class ClinicalTimelineServiceTest {
 final Instant end=Instant.parse("2026-11-06T00:00:00Z");final ClinicalDataProvider data=mock(ClinicalDataProvider.class);@SuppressWarnings("unchecked") final ObjectProvider<Icu05SourceReader> sources=mock(ObjectProvider.class);final ClinicalTimelineService svc=new ClinicalTimelineService(data,sources);
 Patient patient(){Patient p=new Patient();p.id="synthetic-p";p.encounterId="synthetic-stay";p.department="dept";p.admittedAt=end.minusSeconds(3600);return p;}
 Observation row(){Observation o=new Observation();o.patientId="synthetic-p";o.encounterId="synthetic-stay";o.department="dept";o.eventTime=end.minusSeconds(600);o.ingestTime=o.eventTime;o.parameterCode="HR";o.value=80.;o.unit="bpm";o.qualityStatus="valid";return o;}
 @Test void clampsAdmissionAndRejectsForeignStayFutureEventOrFutureIngestion(){var a=row();var foreign=row();foreign.encounterId="other";var future=row();future.eventTime=end.plusSeconds(1);var ingested=row();ingested.ingestTime=end.plusSeconds(1);when(data.observations(anyString(),anyString(),any(),any())).thenReturn(List.of(a,foreign,future,ingested));var r=svc.read(patient(),24,end,"retrospective");assertEquals(patient().admittedAt,r.from);assertEquals(List.of(a),r.observations);assertEquals("unavailable",r.medicationStatus);}
 @Test void knownAtExcludesUnknownAvailabilityAndCandidatesAndDoesNotReadDrugs(){var known=row();var unknown=row();unknown.ingestTime=null;var candidate=row();candidate.clinicalUse="context_only";when(data.observations(anyString(),anyString(),any(),any())).thenReturn(List.of(known,unknown,candidate));var r=svc.read(patient(),24,end,"known_at");assertEquals(List.of(known),r.observations);assertEquals("availability_unknown",r.medicationStatus);verifyNoInteractions(sources);}
 @Test void sourceFailureStaysVisibleInsteadOfMeaningNoRecords(){when(data.observations(anyString(),anyString(),any(),any())).thenThrow(new RuntimeException("sensitive detail"));var r=svc.read(patient(),24,end,"retrospective");assertTrue(r.warnings.stream().anyMatch(x->x.contains("读取失败")));assertFalse(r.warnings.toString().contains("sensitive"));}
 @Test void invalidOrFutureRangesAreRejectedBeforeReading(){assertThrows(ApiException.class,()->svc.read(patient(),721,end,"retrospective"));assertThrows(ApiException.class,()->svc.read(patient(),24,Instant.now().plusSeconds(600),"retrospective"));assertThrows(ApiException.class,()->svc.read(patient(),24,end,"invalid"));verifyNoInteractions(data);}
 @Test void beforeAdmissionReturnsNoObservationOrDrugRead(){var r=svc.read(patient(),1,end.minusSeconds(7200),"retrospective");assertTrue(r.observations.isEmpty());verifyNoInteractions(data,sources);}
 @Test void medicationEventsIncludeStopOfEarlierDrugButNeverInferDurationOrFutureAction(){var d=new Icu05Rules.Drug();d.sourceId="source";d.start=end.minusSeconds(7200);d.items.add(new Icu05Rules.DrugItem("合成药",null));d.actions.add(new Icu05Rules.Action(end.minusSeconds(1800),"pause"));d.actions.add(new Icu05Rules.Action(end.minusSeconds(600),"recovery"));d.actions.add(new Icu05Rules.Action(end.plusSeconds(1),"stop"));var events=ClinicalTimelineService.events(List.of(d),end.minusSeconds(3600),end);assertEquals(2,events.size());assertEquals("暂停",events.get(0).action);assertEquals("恢复",events.get(1).action);assertFalse(events.get(0).availabilityKnown);}
 @Test void summariesKeepCandidateAndUnitUncertaintySeparate(){var p=new ClinicalTimelineService.Packet();p.from=end.minusSeconds(3600);p.asOf=end;p.mode="retrospective";var a=row();var b=row();b.clinicalUse="context_only";b.value=200.;p.observations=List.of(a,b);String facts=ClinicalTimelineService.facts(p,List.of("HR"),false).stream().map(x->x[1]).reduce("",String::concat);assertTrue(facts.contains("未用于数值汇总"));assertFalse(facts.contains("200.0"));assertTrue(facts.contains("最高 80"));assertTrue(facts.contains("2026-11-06 07:50:00（北京时间）"));}
 @Test void foreignDepartmentObservationIsDiscarded(){var a=row();a.department="other";when(data.observations(anyString(),anyString(),any(),any())).thenReturn(List.of(a));assertTrue(svc.read(patient(),24,end,"retrospective").observations.isEmpty());}
 @Test void conflictingTimesAndUnplottableValuesAreNotNumericallySummarized(){var p=new ClinicalTimelineService.Packet();p.from=end.minusSeconds(3600);p.asOf=end;p.mode="retrospective";var a=row();var b=row();b.value=100.;var impossible=row();impossible.eventTime=end.minusSeconds(200);impossible.value=800.;p.observations=List.of(a,b,impossible);String facts=ClinicalTimelineService.facts(p,List.of("HR"),false).stream().map(x->x[1]).reduce("",String::concat);assertTrue(facts.contains("冲突记录"));assertFalse(facts.contains("最高"));assertFalse(facts.contains("800.0"));}
 @Test void failedMedicationSourceCannotBeMarkedAvailable(){when(data.observations(anyString(),anyString(),any(),any())).thenReturn(List.of());var source=mock(Icu05SourceReader.class);when(sources.getIfAvailable()).thenReturn(source);when(source.timelineDrugs(anyString(),anyString(),anyString(),any(),any())).thenThrow(new RuntimeException("password"));var r=svc.read(patient(),24,end,"retrospective");assertEquals("failed",r.medicationStatus);assertFalse(r.warnings.toString().contains("password"));}
}
